/* STUDENT MANAGEMENT SYSTEM - PRN212 GROUP 4
   COMPLETE FRESH INSTALL, SQL Server 2019+ / SSMS.
   Open this ONE file and run ALL with F5 in normal SSMS mode. No SQLCMD required.
   This script creates a NEW database. An existing database is never overwritten.
   If the name already exists, installation stops. Change @DatabaseName below to
   install a separate copy; do not delete the old database just to run this file.
   If setup fails after CREATE DATABASE, the empty database is retained for diagnosis.

   WORKFLOW / MODULE CONTRACT:
   F08 (Nhat): uspRegisterCourse -> CourseEnrollments (no class required).
   F09 (Nhat): vCourseEnrollmentStatus, including registrations not yet assigned.
   F10 (Thuong): uspAssignStudentToClass -> Enrollments (class assignments).
   F11-F13 (Luc): Grades.EnrollmentID still references Enrollments.EnrollmentID.
   F16 (Nhat): reports may join the new registration view.
   Legacy uspEnrollStudent returns an error directing callers to the two new APIs.
   App code must enforce function permissions and own/assigned record scope.

   SAMPLE DATA: original accounts, students, courses, classes and scores retained.
   Added one registration without a class (ST006 / PRN212 / Spring 2027).
   Password hashes/salts are unchanged from the supplied file; no plaintext password
   is known from that file. WPF must implement its declared PBKDF2-SHA256 parameters,
   decoding the stored hash and salt from hexadecimal. No login code is included.
   GPA scale is DEMO configuration. Existing repeat-course/GPA rules are unchanged.

   New API examples (replace parameters with valid IDs):
   DECLARE @RegistrationID int;
   EXEC dbo.uspRegisterCourse @StudentID=..., @CourseID=..., @SemesterID=...,
        @CourseEnrollmentID=@RegistrationID OUTPUT;
   EXEC dbo.uspAssignStudentToClass @CourseEnrollmentID=@RegistrationID, @ClassID=...;

   Completing/dropping: application updates assignment and registration in one
   transaction. Drop the assignment before marking its registration DROPPED.
   Runtime hardening and SQL-backed tests are documented in docs/DATABASE_DEPLOYMENT.md.
*/
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOCOUNT ON;
SET XACT_ABORT ON;
DECLARE @DatabaseName sysname=N'PRN212_StudentManagement_G4_Demo';
IF @@TRANCOUNT<>0 THROW 51400,'Run outside an existing transaction.',1;
IF DB_ID(@DatabaseName) IS NOT NULL
BEGIN
 ;THROW 51000,'Database already exists. Nothing changed. Choose another @DatabaseName for a fresh copy.',1;
END;
DECLARE @CreateSql nvarchar(max)=N'CREATE DATABASE '+QUOTENAME(@DatabaseName)+N';';
EXEC sys.sp_executesql @CreateSql;
DECLARE @SetupSql nvarchar(max)=N'USE '+QUOTENAME(@DatabaseName)+N';
SET QUOTED_IDENTIFIER ON;
SET ANSI_NULLS ON;
SET NOCOUNT ON;
SET XACT_ABORT ON;
BEGIN TRY
 BEGIN TRANSACTION;
EXEC sys.sp_executesql N''CREATE TABLE dbo.Roles (
 RoleID int IDENTITY(1,1) PRIMARY KEY,
 RoleCode varchar(30) NOT NULL UNIQUE,
 RoleName nvarchar(80) NOT NULL
);
CREATE TABLE dbo.Permissions (
 PermissionID int IDENTITY(1,1) PRIMARY KEY,
 FunctionCode char(3) NOT NULL UNIQUE,
 FunctionName nvarchar(100) NOT NULL,
 CONSTRAINT CK_Permissions_FunctionCode CHECK (FunctionCode LIKE ''''F0[1-9]'''' OR FunctionCode LIKE ''''F1[0-9]'''' OR FunctionCode = ''''F20'''')
);
CREATE TABLE dbo.RolePermissions (
 RoleID int NOT NULL REFERENCES dbo.Roles(RoleID),
 PermissionID int NOT NULL REFERENCES dbo.Permissions(PermissionID),
 CONSTRAINT PK_RolePermissions PRIMARY KEY(RoleID, PermissionID)
);
CREATE TABLE dbo.Users (
 UserID int IDENTITY(1,1) PRIMARY KEY,
 Username nvarchar(80) NOT NULL UNIQUE,
 PasswordHash varchar(256) NOT NULL,
 PasswordSalt varchar(64) NOT NULL,
 PasswordAlgorithm varchar(50) NOT NULL DEFAULT ''''PBKDF2-SHA256'''',
 PasswordIterations int NOT NULL DEFAULT 210000 CHECK (PasswordIterations >= 100000),
 DisplayName nvarchar(120) NOT NULL,
 Email nvarchar(255) NULL,
 IsActive bit NOT NULL DEFAULT 1,
 MustChangePassword bit NOT NULL DEFAULT 1,
 CreatedAt datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
 UpdatedAt datetime2(0) NULL,
 RowVer rowversion
);
CREATE UNIQUE INDEX UX_Users_Email_NotNull ON dbo.Users(Email) WHERE Email IS NOT NULL;
CREATE TABLE dbo.UserRoles (
 UserID int NOT NULL REFERENCES dbo.Users(UserID),
 RoleID int NOT NULL REFERENCES dbo.Roles(RoleID),
 CONSTRAINT PK_UserRoles PRIMARY KEY(UserID,RoleID)
);
CREATE TABLE dbo.Departments (
 DepartmentID int IDENTITY(1,1) PRIMARY KEY,
 DepartmentCode varchar(20) NOT NULL UNIQUE,
 DepartmentName nvarchar(120) NOT NULL,
 IsActive bit NOT NULL DEFAULT 1
);
CREATE TABLE dbo.Students (
 StudentID int IDENTITY(1,1) PRIMARY KEY,
 StudentCode varchar(20) NOT NULL UNIQUE,
 UserID int NULL REFERENCES dbo.Users(UserID),
 FullName nvarchar(120) NOT NULL,
 DateOfBirth date NULL,
 Email nvarchar(255) NULL,
 Phone varchar(30) NULL,
 DepartmentID int NULL REFERENCES dbo.Departments(DepartmentID),
 EnrollmentDate date NULL,
 StudentStatus varchar(20) NOT NULL DEFAULT ''''ACTIVE'''',
 CreatedAt datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
 RowVer rowversion,
 CONSTRAINT CK_Students_Status CHECK (StudentStatus IN (''''ACTIVE'''',''''INACTIVE'''',''''GRADUATED'''',''''SUSPENDED''''))
);
/* Nullable UserID: filtered unique index permits many students without login accounts */
CREATE UNIQUE INDEX UX_Students_UserID_NotNull ON dbo.Students(UserID) WHERE UserID IS NOT NULL;
CREATE TABLE dbo.Lecturers (
 LecturerID int IDENTITY(1,1) PRIMARY KEY,
 LecturerCode varchar(20) NOT NULL UNIQUE,
 UserID int NULL REFERENCES dbo.Users(UserID),
 FullName nvarchar(120) NOT NULL,
 DepartmentID int NULL REFERENCES dbo.Departments(DepartmentID),
 IsActive bit NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX UX_Lecturers_UserID_NotNull ON dbo.Lecturers(UserID) WHERE UserID IS NOT NULL;
CREATE TABLE dbo.AcademicStaff (
 StaffID int IDENTITY(1,1) PRIMARY KEY,
 StaffCode varchar(20) NOT NULL UNIQUE,
 UserID int NULL REFERENCES dbo.Users(UserID),
 FullName nvarchar(120) NOT NULL,
 DepartmentID int NULL REFERENCES dbo.Departments(DepartmentID),
 IsActive bit NOT NULL DEFAULT 1
);
CREATE UNIQUE INDEX UX_AcademicStaff_UserID_NotNull ON dbo.AcademicStaff(UserID) WHERE UserID IS NOT NULL;
CREATE TABLE dbo.Courses (
 CourseID int IDENTITY(1,1) PRIMARY KEY,
 CourseCode varchar(20) NOT NULL UNIQUE,
 CourseName nvarchar(150) NOT NULL,
 Credits tinyint NOT NULL CHECK(Credits BETWEEN 1 AND 15),
 DepartmentID int NULL REFERENCES dbo.Departments(DepartmentID),
 IsActive bit NOT NULL DEFAULT 1
);
CREATE TABLE dbo.Semesters (
 SemesterID int IDENTITY(1,1) PRIMARY KEY,
 SemesterCode varchar(30) NOT NULL UNIQUE,
 SemesterName nvarchar(100) NOT NULL,
 StartDate date NOT NULL,
 EndDate date NOT NULL,
 CONSTRAINT CK_Semesters_Dates CHECK (EndDate >= StartDate)
);
CREATE TABLE dbo.Classes (
 ClassID int IDENTITY(1,1) PRIMARY KEY,
 ClassCode varchar(30) NOT NULL UNIQUE,
 CourseID int NOT NULL REFERENCES dbo.Courses(CourseID),
 SemesterID int NOT NULL REFERENCES dbo.Semesters(SemesterID),
 LecturerID int NULL REFERENCES dbo.Lecturers(LecturerID),
 Capacity int NULL CHECK(Capacity > 0),
 ScheduleNote nvarchar(250) NULL,
 ClassStatus varchar(15) NOT NULL DEFAULT ''''OPEN'''',
 CONSTRAINT CK_Classes_Status CHECK(ClassStatus IN (''''OPEN'''',''''CLOSED'''',''''CANCELLED''''))
);
/* F08: course registration may exist before a class is assigned. */
CREATE TABLE dbo.CourseEnrollments (
 CourseEnrollmentID int IDENTITY(1,1) NOT NULL CONSTRAINT PK_CourseEnrollments PRIMARY KEY,
 StudentID int NOT NULL REFERENCES dbo.Students(StudentID),
 CourseID int NOT NULL REFERENCES dbo.Courses(CourseID),
 SemesterID int NOT NULL REFERENCES dbo.Semesters(SemesterID),
 RegistrationDate datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
 RegistrationStatus varchar(15) NOT NULL DEFAULT ''''REGISTERED'''',
 RowVer rowversion,
 CONSTRAINT UQ_CourseEnrollments_Student_Course_Term UNIQUE(StudentID,CourseID,SemesterID),
 CONSTRAINT CK_CourseEnrollments_Status CHECK(RegistrationStatus IN (''''REGISTERED'''',''''DROPPED'''',''''COMPLETED''''))
);
CREATE INDEX IX_CourseEnrollments_Course_Term ON dbo.CourseEnrollments(CourseID,SemesterID);
/* F10: Enrollments holds class assignments; Grades still references EnrollmentID. */
CREATE TABLE dbo.Enrollments (
 EnrollmentID int IDENTITY(1,1) PRIMARY KEY,
 CourseEnrollmentID int NOT NULL REFERENCES dbo.CourseEnrollments(CourseEnrollmentID),
 StudentID int NOT NULL REFERENCES dbo.Students(StudentID),
 ClassID int NOT NULL REFERENCES dbo.Classes(ClassID),
 EnrollmentDate datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
 EnrollmentStatus varchar(15) NOT NULL DEFAULT ''''ENROLLED'''',
 RowVer rowversion,
 CONSTRAINT UQ_Enrollments_Student_Class UNIQUE(StudentID,ClassID),
 CONSTRAINT CK_Enrollments_Status CHECK(EnrollmentStatus IN (''''ENROLLED'''',''''DROPPED'''',''''COMPLETED''''))
);
CREATE UNIQUE INDEX UX_Enrollments_ActiveRegistration ON dbo.Enrollments(CourseEnrollmentID) WHERE EnrollmentStatus <> ''''DROPPED'''';
CREATE TABLE dbo.Grades (
 GradeID int IDENTITY(1,1) PRIMARY KEY,
 EnrollmentID int NOT NULL UNIQUE REFERENCES dbo.Enrollments(EnrollmentID),
 FinalScore decimal(5,2) NOT NULL CHECK(FinalScore BETWEEN 0 AND 10),
 IsPublished bit NOT NULL DEFAULT 0,
 UpdatedByUserID int NULL REFERENCES dbo.Users(UserID),
 UpdatedAt datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME(),
 RowVer rowversion
);
/* Grading policy is configurable and intentionally NOT hard-coded in the GPA view. */
CREATE TABLE dbo.GradeScale (
 GradeScaleID int IDENTITY(1,1) PRIMARY KEY,
 MinScore decimal(5,2) NOT NULL,
 MaxScore decimal(5,2) NOT NULL,
 GradePoint decimal(3,2) NOT NULL,
 GradeLetter varchar(5) NOT NULL,
 IsActive bit NOT NULL DEFAULT 1,
 CONSTRAINT CK_GradeScale_Range CHECK(MinScore BETWEEN 0 AND 10 AND MaxScore BETWEEN 0 AND 10 AND MinScore <= MaxScore),
 CONSTRAINT CK_GradeScale_Point CHECK(GradePoint BETWEEN 0 AND 4)
);
/* Academic records are distinct from student profile, and can be archived. */
CREATE TABLE dbo.StudentRecords (
 RecordID int IDENTITY(1,1) PRIMARY KEY,
 StudentID int NOT NULL REFERENCES dbo.Students(StudentID),
 RecordType nvarchar(60) NOT NULL,
 DocumentNumber nvarchar(80) NULL,
 RecordTitle nvarchar(180) NOT NULL,
 RecordContent nvarchar(max) NULL,
 RecordDate date NOT NULL DEFAULT CONVERT(date,GETDATE()),
 IsArchived bit NOT NULL DEFAULT 0,
 CreatedByUserID int NULL REFERENCES dbo.Users(UserID),
 CreatedAt datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME()
);
CREATE TABLE dbo.AuditLogs (
 AuditID bigint IDENTITY(1,1) PRIMARY KEY,
 ActorUserID int NULL REFERENCES dbo.Users(UserID),
 ActionName varchar(80) NOT NULL,
 EntityName varchar(80) NOT NULL,
 EntityKey nvarchar(100) NULL,
 Details nvarchar(2000) NULL,
 HappenedAt datetime2(0) NOT NULL DEFAULT SYSUTCDATETIME()
);
CREATE INDEX IX_Enrollments_Student ON dbo.Enrollments(StudentID);
CREATE INDEX IX_Enrollments_Class ON dbo.Enrollments(ClassID);
CREATE INDEX IX_Classes_Course_Semester ON dbo.Classes(CourseID,SemesterID);
CREATE INDEX IX_Grades_Published ON dbo.Grades(IsPublished);
CREATE INDEX IX_Records_BusinessKey ON dbo.StudentRecords(StudentID,RecordType,DocumentNumber);
CREATE INDEX IX_Records_Student ON dbo.StudentRecords(StudentID,IsArchived);
CREATE INDEX IX_AuditLogs_Time ON dbo.AuditLogs(HappenedAt DESC);

