INSERT dbo.CourseEnrollments(StudentID,CourseID,SemesterID,RegistrationStatus)
SELECT a.StudentID,c.CourseID,c.SemesterID,
 CASE WHEN MAX(CASE WHEN a.EnrollmentStatus=''''COMPLETED'''' THEN 1 ELSE 0 END)=1
 THEN ''''COMPLETED'''' ELSE ''''REGISTERED'''' END
FROM @SeedAssignments a JOIN dbo.Classes c ON c.ClassID=a.ClassID
GROUP BY a.StudentID,c.CourseID,c.SemesterID;
INSERT dbo.Enrollments(CourseEnrollmentID,StudentID,ClassID,EnrollmentStatus)
SELECT r.CourseEnrollmentID,a.StudentID,a.ClassID,a.EnrollmentStatus
FROM @SeedAssignments a JOIN dbo.Classes c ON c.ClassID=a.ClassID
JOIN dbo.CourseEnrollments r ON r.StudentID=a.StudentID AND r.CourseID=c.CourseID AND r.SemesterID=c.SemesterID;
